javascript:make new contact.code:
const axios = require('axios');

const apiKey = 'YOUR_API_KEY';
const url = 'https://app.jobnimbus.com/api1/contacts';
const body = {
  "first_name": "",
  "last_name": "",
  "record_type_name": "",
  "status_name": "",
  "geo": {
    "lon": 0,
    "lat": 0
  }
};

axios.post(url, body, {
  headers: {
    Authorization: `bearer ${apiKey}`
  }
})
.then(response => {
  if (response.status === 201) {
    console.log(response.data);
  } else {
    console.log(`Error: ${response.status}`);
  }
})
.catch(error => {
  console.log(`Error: ${error.message}`);
});
